## Submitted testbench
```systemverilog
module tb;
  // ------------------------------------------------------------
  //  Testbench signals
  // ------------------------------------------------------------
  logic        clk        = 0;
  logic        rst        = 0;
  logic [7:0]  s_axis_tdata = '0;
  logic        s_axis_tvalid = 0;
  logic        s_axis_tready;
  logic [15:0] prescale     = 16'h0002;  // preset = 2
  // DUT output connections (unused but must be tied)
  logic        txd;
  logic        busy;
  logic [7:0]  m_axis_tdata_dummy;
  logic        m_axis_tvalid_dummy;
  logic        m_axis_tready_dummy;
  logic        tx_busy_dummy;
  logic        rx_busy_dummy;
  logic        rx_overrun_error_dummy;
  logic        rx_frame_error_dummy;

  // ------------------------------------------------------------
  //  Clock generation
  // ------------------------------------------------------------
  always #5 clk = ~clk;  // 100 MHz clock

  // ------------------------------------------------------------
  //  Reset sequence
  // ------------------------------------------------------------
  initial begin
    rst = 1;
    #20;
    rst = 0;
    #20;
  end

  // ------------------------------------------------------------
  //  DUT instantiation (uart, default PARAMETER values)
  // ------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata (m_axis_tdata_dummy),
    .m_axis_tvalid(m_axis_tvalid_dummy),
    .m_axis_tready(m_axis_tready_dummy),
    .rxd          (1'b1),
    .txd          (txd),
    .tx_busy      (tx_busy_dummy),
    .rx_busy      (rx_busy_dummy),
    .rx_overrun_error(rx_overrun_error_dummy),
    .rx_frame_error (rx_frame_error_dummy),
    .prescale     (prescale)
  );

  // ------------------------------------------------------------
  //  Simple stimulus: send two back‑to‑back frames
  //      first  = 8'h12
  //      second = 8'h34
  //  Then wait long enough for the coverage point to be hit.
  // ------------------------------------------------------------
  initial begin
    // give the design time after reset
    #50;

    // ---- first frame (0x12) ----
    @(posedge s_axis_tready);
    s_axis_tdata  <= 8'h12;
    s_axis_tvalid <= 1'b1;
    @(posedge clk);
    s_axis_tvalid <= 1'b0;

    // wait until the master is ready for the next beat
    wait(s_axis_tready);
    // ---- second frame (0x34) ----
    s_axis_tdata  <= 8'h34;
    s_axis_tvalid <= 1'b1;
    @(posedge clk);
    s_axis_tvalid <= 1'b0;

    // allow sufficient time for internal counters to reach the
    // condition described in cov_T9 (prescale = 2, bit_cnt == 2,
    // etc.) before terminating the simulation
    #50000;

    $finish;
  end

endmodule
```

